@font-face { font-family: "IBM Plex Sans"; font-style: normal; font-weight: 600; font-display: swap; src: url("./fonts/ibm-plex-sans-latin-600-normal.woff2") format("woff2"); }
@font-face { font-family: "IBM Plex Sans"; font-style: normal; font-weight: 700; font-display: swap; src: url("./fonts/ibm-plex-sans-latin-700-normal.woff2") format("woff2"); }
@font-face { font-family: "IBM Plex Mono"; font-style: normal; font-weight: 400; font-display: swap; src: url("./fonts/ibm-plex-mono-latin-400-normal.woff2") format("woff2"); }
@font-face { font-family: "IBM Plex Mono"; font-style: normal; font-weight: 500; font-display: swap; src: url("./fonts/ibm-plex-mono-latin-500-normal.woff2") format("woff2"); }
@font-face { font-family: "IBM Plex Mono"; font-style: normal; font-weight: 600; font-display: swap; src: url("./fonts/ibm-plex-mono-latin-600-normal.woff2") format("woff2"); }

/* D12 design tokens (rearch/06; colour and type per console-radar-theme). Dark is the source of truth.
 * Navy grounds + enterprise blue accent (agent-builder parity). Components NEVER hardcode colors — tokens only. */
:root,
html[data-theme="dark"] {
  --bg-primary: #0a0f1a;
  --bg-secondary: #101828;
  --bg-tertiary: #16233a;
  --bg-elevated: #101828;

  --text-primary: #e6edf7;
  --text-secondary: #8494ac;
  --text-tertiary: #5a6a85;
  --text-disabled: #475569;
  --text-inverse: #0a0f1a;

  --border-primary: #1e2a40;
  --border-secondary: #2a3a58;
  --border-focus: #2563eb;

  /* Dark enough that white --text-on-accent clears WCAG AA 4.5:1 on small button labels. */
  --accent-primary: #2563eb;
  --accent-primary-hover: #1d4ed8;
  --accent-primary-light: #1e3a8a;
  --text-on-accent: #ffffff;
  --accent-success: #34d399;
  --accent-warning: #ffb547;
  --accent-error: #f87171;
  --accent-teal: #2dd4bf;
  --accent-info: #60a5fa;
  --accent-fuchsia: #e879f9;
  --accent-sky: #38bdf8;
  --accent-violet: #a78bfa;

  --surface-card: #101828;
  --surface-hover: #16233a;
  --surface-active: #1e2a40;
  --surface-selected: #1e3a8a;
  /* legacy globals.css (controller desk D4c): the modal backdrop, and the field ground the desk's
     text inputs sit on (legacy writes it as `bg-[var(--bg-primary)]`). */
  --bg-overlay: rgba(0, 0, 0, 0.6);
  --surface-input: #0a0f1a;

  --grid-line: rgba(59, 130, 246, 0.08);
  --radius-md: 0.375rem;
  --radius-lg: 0.5rem;
  --radius-xl: 0.75rem;

  --font-sans: "IBM Plex Sans", ui-sans-serif, system-ui, sans-serif;
  --font-mono: "IBM Plex Mono", ui-monospace, Menlo, monospace;
  --shadow-sm: 0 1px 2px 0 #0000004d;
  --shadow-md: 0 4px 6px -1px #0006, 0 2px 4px -1px #0000004d;
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.5), 0 4px 6px -2px rgba(0, 0, 0, 0.3); /* legacy globals.css (controller desk D2) */

  --sky-bg: rgba(14, 165, 233, 0.22); --sky-bd: rgba(56, 189, 248, 0.45); --sky-tx: #bae6fd;
  --emer-bg: rgba(16, 185, 129, 0.22); --emer-bd: rgba(52, 211, 153, 0.45); --emer-tx: #a7f3d0;
  --red-bg: rgba(239, 68, 68, 0.2); --red-bd: rgba(248, 113, 113, 0.45); --red-tx: #fecaca;
  --tag-early-bg: rgba(16, 185, 129, 0.2); --tag-early-tx: #6ee7b7; --tag-early-bd: rgba(16, 185, 129, 0.3);
  --tag-delay-bg: rgba(245, 158, 11, 0.2); --tag-delay-tx: #fcd34d; --tag-delay-bd: rgba(245, 158, 11, 0.3);
  --cell-green-bg: rgba(16, 185, 129, 0.14); --cell-green-tx: #6ee7b7;
  --cell-amber-bg: rgba(245, 158, 11, 0.18); --cell-amber-tx: #fcd34d;
  --cell-red-bg: rgba(239, 68, 68, 0.18); --cell-red-tx: #fca5a5;

  --hourW: 150px;
  --rowH: 30px;
  --labelW: 120px;
}

/* Light theme (legacy parity — toggled via html[data-theme="light"]). */
html[data-theme="light"] {
  --bg-primary: #f8f9fa;
  --bg-secondary: #ffffff;
  --bg-tertiary: #f1f3f5;
  --bg-elevated: #ffffff;

  --text-primary: #1a1d29;
  --text-secondary: #4a5568;
  --text-tertiary: #718096;
  --text-disabled: #cbd5e0;
  --text-inverse: #ffffff;

  --border-primary: #e2e8f0;
  --border-secondary: #cbd5e0;
  --border-focus: #3b82f6;

  --accent-primary: #2563eb;
  --accent-primary-hover: #1d4ed8;
  --accent-primary-light: #dbeafe;
  --text-on-accent: #ffffff;
  --accent-success: #059669;
  --accent-warning: #b45309;
  --accent-error: #b91c1c;
  --accent-teal: #0d9488;
  --accent-info: #2563eb;
  --accent-fuchsia: #c026d3;
  --accent-sky: #0284c7;
  --accent-violet: #7c3aed;

  --surface-card: #ffffff;
  --surface-hover: #f1f5f9;
  --surface-active: #e2e8f0;
  --surface-selected: #eff6ff;
  --bg-overlay: rgba(0, 0, 0, 0.4);
  --surface-input: #ffffff;

  --grid-line: rgba(37, 99, 235, 0.1);
  --shadow-sm: 0 1px 3px 0 #0000001a, 0 1px 2px -1px #0000001a;
  --shadow-md: 0 4px 6px -1px #0000001a, 0 2px 4px -1px #0000000f;
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05); /* legacy globals.css (controller desk D2) */

  --sky-bg: rgba(14, 165, 233, 0.2); --sky-bd: rgba(2, 132, 199, 0.4); --sky-tx: #075985;
  --emer-bg: rgba(16, 185, 129, 0.18); --emer-bd: rgba(5, 150, 105, 0.4); --emer-tx: #065f46;
  --red-bg: rgba(239, 68, 68, 0.16); --red-bd: rgba(220, 38, 38, 0.45); --red-tx: #991b1b;
  --tag-early-bg: rgba(16, 185, 129, 0.16); --tag-early-tx: #047857; --tag-early-bd: rgba(16, 185, 129, 0.3);
  --tag-delay-bg: rgba(245, 158, 11, 0.18); --tag-delay-tx: #b45309; --tag-delay-bd: rgba(245, 158, 11, 0.35);
  --cell-green-bg: rgba(16, 185, 129, 0.12); --cell-green-tx: #047857;
  --cell-amber-bg: rgba(245, 158, 11, 0.16); --cell-amber-tx: #b45309;
  --cell-red-bg: rgba(239, 68, 68, 0.12); --cell-red-tx: #b91c1c;
}

body {
  margin: 0;
  background: var(--bg-primary);
  color: var(--text-primary);
  font-family: var(--font-sans);
  font-size: 14px;
}

.mono {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}

.pill {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  padding: 2px 7px;
  font-size: 10px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  line-height: 1.4;
}
.pill.info { background: color-mix(in srgb, var(--accent-info), transparent 82%); color: var(--accent-info); }
.pill.warn { background: color-mix(in srgb, var(--accent-warning), transparent 80%); color: var(--accent-warning); }
.pill.ok { background: color-mix(in srgb, var(--accent-success), transparent 80%); color: var(--accent-success); }
.pill.err { background: color-mix(in srgb, var(--accent-error), transparent 82%); color: var(--accent-error); }
.pill.neutral { background: var(--surface-hover); color: var(--text-secondary); }
.pill.fuchsia { background: color-mix(in srgb, var(--accent-fuchsia), transparent 85%); color: var(--accent-fuchsia); }
.pill.sky { background: color-mix(in srgb, var(--accent-sky), transparent 85%); color: var(--accent-sky); }
.pill.violet { background: color-mix(in srgb, var(--accent-violet), transparent 85%); color: var(--accent-violet); }
/* A pill used as a toggle reads as the Radar's outlined buttons: pressed is the accent, not the info hue. */
button.pill[aria-pressed] { border: 1px solid var(--border-secondary); background: transparent; color: var(--text-secondary); cursor: pointer; }
button.pill[aria-pressed="true"] { background: var(--accent-primary-light); border-color: var(--accent-primary); color: var(--text-primary); }
button.pill[aria-pressed]:disabled { opacity: 0.45; cursor: default; }

.rcard {
  background: var(--surface-card);
  border: 1px solid var(--border-primary);
  border-radius: var(--radius-xl);
  padding: 13px 14px;
  margin-bottom: 10px;
  box-shadow: var(--shadow-sm);
  cursor: pointer;
  transition: border-color 0.15s;
}
.rcard:hover { border-color: var(--border-secondary); }
.rcard.active { border-color: var(--accent-warning); box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent-warning), transparent 55%); }

.glabel {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--text-tertiary);
  margin: 14px 0 8px;
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: transparent;
  color: var(--text-secondary);
  border: 1px solid transparent;
  border-radius: var(--radius-md);
  padding: 6px 12px;
  font-size: 12.5px;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  text-decoration: none;
  transition: 0.12s;
}
.chip:hover { background: var(--surface-hover); color: var(--text-primary); }
.chip.active { background: var(--accent-primary); color: var(--text-on-accent); }

.btn {
  border: 1px solid var(--border-secondary);
  background: var(--bg-secondary);
  color: var(--text-primary);
  border-radius: var(--radius-md);
  padding: 8px 16px;
  font-size: 12.5px;
  cursor: pointer;
}
.btn.primary { background: var(--accent-primary); border-color: var(--accent-primary); color: var(--text-on-accent); }
.btn.danger { background: color-mix(in srgb, var(--accent-error), transparent 85%); border-color: var(--accent-error); color: var(--accent-error); }

input {
  background: var(--bg-secondary);
  border: 1px solid var(--border-primary);
  color: var(--text-primary);
  border-radius: var(--radius-md);
  padding: 8px 12px;
  font-size: 13px;
}
input:focus { outline: none; border-color: var(--border-focus); }

.banner {
  background: color-mix(in srgb, var(--accent-info), transparent 85%);
  color: var(--accent-info);
  padding: 8px 16px;
  font-size: 12.5px;
  text-align: center;
}

/* Weekly-risk heatmap table (06 §components: surface-card rows, tabular-nums). */
.risk-table {
  border-collapse: collapse;
  width: 100%;
  font-size: 12.5px;
}
.risk-table th {
  text-align: right;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--text-tertiary);
  padding: 6px 12px;
  border-bottom: 1px solid var(--border-primary);
}
.risk-table th:first-child,
.risk-table td:first-child { text-align: left; }
.risk-table td {
  text-align: right;
  padding: 6px 12px;
  border-bottom: 1px solid var(--border-primary);
  color: var(--text-secondary);
}
.risk-table td.red { color: var(--accent-error); font-weight: 700; }
.risk-table tr.hot td:first-child { color: var(--text-primary); font-weight: 700; }

/* Heatmap cell intensity (relative-to-busiest-cell display tint; bands are tenant config). */
.risk-table td.heat-1 { background: color-mix(in srgb, var(--accent-warning), transparent 88%); }
.risk-table td.heat-2 { background: color-mix(in srgb, var(--accent-warning), transparent 74%); }
.risk-table td.heat-3 { background: color-mix(in srgb, var(--accent-error), transparent 72%); }

/* Crew name rendered as a legality drill-down (link-styled button). */
.crewlink {
  background: none;
  border: none;
  padding: 0;
  font: inherit;
  color: var(--accent-info);
  cursor: pointer;
  text-decoration: underline dotted;
  text-underline-offset: 2px;
}
.crewlink:hover { color: var(--accent-primary-hover); }

